import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../app_helpers.dart';
import '../database/db_helper.dart';
import '../widgets/tx_tile.dart';

class Students extends StatefulWidget{final VoidCallback changed;const Students({super.key,required this.changed});@override State<Students> createState()=>_StudentsState();}
class _StudentsState extends State<Students>{String q='';Future<void> form([Map<String,dynamic>? e])async{final ok=await Navigator.push(context,MaterialPageRoute(builder:(_)=>StudentForm(row:e)));if(ok==true){setState((){});widget.changed();}}@override Widget build(BuildContext c)=>Column(children:[heading('Data siswa','Kelola data peserta pembayaran',action:IconButton(onPressed:()=>form(),icon:const Icon(Icons.add_circle,color:blue,size:30))),Padding(padding:const EdgeInsets.symmetric(horizontal:18),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari nama atau NIS siswa'))),Expanded(child:FutureBuilder(future:DB.i.all('siswa'),builder:(c,s){final rows=(s.data??[]).where((e)=>'${e['nama_siswa']} ${e['nis']}'.toLowerCase().contains(q.toLowerCase())).toList();return rows.isEmpty?const Center(child:Text('Belum ada siswa')):ListView(padding:const EdgeInsets.all(18),children:[Text('${rows.length} siswa'),const SizedBox(height:8),card(Column(children:rows.map((e)=>ListTile(title:Text(e['nama_siswa'],style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${e['nis']} • ${e['kelas']??''}'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>StudentDetail(row:e,onEdit:()=>form(e)))))).toList()))]);}))]);}
class StudentForm extends StatefulWidget{final Map<String,dynamic>? row;const StudentForm({super.key,this.row});@override State<StudentForm> createState()=>_StudentFormState();}
class _StudentFormState extends State<StudentForm>{final nis=TextEditingController(),name=TextEditingController(),kelas=TextEditingController(),major=TextEditingController();@override void initState(){super.initState();final e=widget.row;if(e!=null){nis.text=e['nis']??'';name.text=e['nama_siswa']??'';kelas.text=e['kelas']??'';major.text=e['jurusan']??'';}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.row==null?'Tambah siswa':'Edit siswa')),body:ListView(padding:const EdgeInsets.all(18),children:[label('NIS'),TextField(controller:nis),label('Nama siswa'),TextField(controller:name),label('Kelas'),TextField(controller:kelas),label('Jurusan'),TextField(controller:major),const SizedBox(height:24),btn('Simpan siswa',()async{if(nis.text.isEmpty||name.text.isEmpty){msg(c,'NIS dan nama wajib diisi');return;}final d={'nis':nis.text,'nama_siswa':name.text,'kelas':kelas.text,'jurusan':major.text};try{if(widget.row==null)await DB.i.add('siswa',d);else await DB.i.edit('siswa','id_siswa',widget.row!['id_siswa'],d);if(c.mounted)Navigator.pop(c,true);}catch(_){msg(c,'NIS sudah digunakan');}}),if(widget.row!=null)TextButton(onPressed:()async{if(await confirm(c,'Hapus siswa?')){await DB.i.del('siswa','id_siswa',widget.row!['id_siswa']);if(c.mounted)Navigator.pop(c,true);}},child:const Text('Hapus siswa',style:TextStyle(color:red))) ]));}
class StudentDetail extends StatelessWidget{final Map<String,dynamic> row;final VoidCallback onEdit;const StudentDetail({super.key,required this.row,required this.onEdit});@override Widget build(BuildContext c)=>FutureBuilder(future:DB.i.tx(),builder:(c,s){final rows=(s.data??[]).where((e)=>e['id_siswa']==row['id_siswa']).toList();final total=rows.where((e)=>e['jenis']=='Pemasukan').fold<double>(0,(a,e)=>a+(e['jumlah'] as num).toDouble());return Scaffold(appBar:AppBar(title:const Text('Detail siswa')),body:ListView(padding:const EdgeInsets.all(18),children:[card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(row['nama_siswa'],style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text('NIS: ${row['nis']}'),Text('Kelas: ${row['kelas']}'),Text('Jurusan: ${row['jurusan']}')])),const SizedBox(height:12),card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('TOTAL PEMBAYARAN'),Text(money.format(total),style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold,color:navy))])),label('Riwayat pembayaran'),card(Column(children:rows.isEmpty?[const Text('Belum ada riwayat')]:rows.map((e)=>TxTile(e)).toList())),const SizedBox(height:16),btn('Edit data siswa',onEdit)]));});}
